    # For runs on the right, fill row-wise inward from any marker.
    right_rows = [r for r in range(h) if grid[r][w-1] == 3]
    if right_rows:
        for r in range(h):
            marks = [c for c,v in enumerate(grid[r]) if v == 7]
            if marks:
                c0 = min(marks)
                out[r][c0] = 4
                for c in range(c0+1,w-1):
                    if grid[r][c] == 6: out[r][c] = 0
    # Repeated side run pattern: vertical band from the edge stripe location.
    for r in range(h):
