def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # For each 3-run at a side, extend the nearest interior seed toward that side.
    for edge_col in (0, w - 1):
        rows = [r for r in range(h) if grid[r][edge_col] == 3]
        if not rows: continue
        # Find marked pixels adjacent to this boundary run.
        seeds = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
                 if grid[r][c] not in (bg,3)]
        if not seeds: continue
        # Select the closest seed, project it across its own row.
        sr, sc, color = min(seeds, key=lambda p: abs(p[1]-edge_col))
        out[sr][sc] = 4
        if edge_col == 0:
            for x in range(sc+1, w):
                if grid[sr][x] == bg: out[sr][x] = color
        else:
            for x in range(0, sc):
